import java.time.*;import java.time.temporal.ChronoUnit;abstract class Assignment{String title;LocalDate due;int max;Assignment(String t,int m,LocalDate d){title=t;max=m;due=d;}abstract double applyPenalty(double marks,long lateDays);}class CodingAssignment extends Assignment{CodingAssignment(String t,int m,LocalDate d){super(t,m,d);}double applyPenalty(double x,long d){return x*Math.max(0,1-.10*d);}}class WrittenAssignment extends Assignment{WrittenAssignment(String t,int m,LocalDate d){super(t,m,d);}double applyPenalty(double x,long d){return x*Math.max(0,1-.20*d);}}class Student{String name;Student(String n){name=n;}}class Submission{Student student;Assignment assignment;LocalDate submittedOn;String status="Submitted";double finalMarks;Submission(Student s,Assignment a,LocalDate d){student=s;assignment=a;submittedOn=d;}void grade(double awarded){if(!status.equals("Submitted"))throw new IllegalStateException();long late=Math.max(0,ChronoUnit.DAYS.between(assignment.due,submittedOn));finalMarks=assignment.applyPenalty(awarded,late);status="Graded";}void resubmit(LocalDate d){if(status.equals("Graded"))throw new IllegalStateException();submittedOn=d;}}public class Main{public static void main(String[]a){}}